    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _period_name_plan p JOIN unified_sites u ON u.id = p.site_id
     WHERE u.period_name IS DISTINCT FROM p.new_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'period_name derivation: % planned row(s) do not hold the new value', bad;
