        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'period_name derivation: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = '2026-09-22_mechanical-period-name-rollback'
       AND (l.table_name <> 'unified_sites' OR l.column_name <> 'period_name');
    IF bad > 0 THEN
