SELECT 'journal rows for the rollback stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = '2026-09-22_mechanical-period-name-rollback'
UNION ALL
SELECT 'planned rows still holding the written value', count(*)::text
  FROM planned p JOIN unified_sites u ON u.id = p.site_id
 WHERE u.period_name IS NOT DISTINCT FROM p.written
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds'
UNION ALL
SELECT 'temp table _period_name_plan left behind',
       (to_regclass('pg_temp._period_name_plan') IS NOT NULL)::int::text
